fn toggle_case(s: Vec<char>) -> Vec<char> {
    s.into_iter()
        .map(|c| {
            if ('a'..='z').contains(&c) {
                // ASCII lowercase -> uppercase by subtracting 32
                let code = c as u32 - 32;
                char::from_u32(code).unwrap()
            } else if ('A'..='Z').contains(&c) {
                // ASCII uppercase -> lowercase by adding 32
                let code = c as u32 + 32;
                char::from_u32(code).unwrap()
            } else {
                c
            }
        })
        .collect()
}